const searchActiveChunkIDsFTS = `-- name: SearchActiveChunkIDsFTS :many
SELECT f.chunk_id
FROM document_chunks_fts f
JOIN document_chunks c ON c.id = f.chunk_id
JOIN documents d ON d.id = c.document_id
WHERE f.content MATCH ?1
  AND f.status = 'ACTIVE'
  AND d.status = 'ACTIVE'
  AND (d.char_count = 0 OR d.char_count >= ?2)
  AND (?3 IS NULL OR ?3 = '' OR f.domain = ?3)
  AND (?4 IS NULL OR ?4 = '' OR f.applicable_cohort = 'ALL' OR (',' || REPLACE(f.applicable_cohort, ' ', '') || ',') LIKE ('%,' || ?4 || ',%'))
ORDER BY rank
LIMIT ?5
`

type SearchActiveChunkIDsFTSParams struct {
	Query        string      `json:"query"`
	MinCharCount int64       `json:"min_char_count"`
	Domain       interface{} `json:"domain"`
	Cohort       interface{} `json:"cohort"`
	Limit        int64       `json:"limit"`
}

func (q *Queries) SearchActiveChunkIDsFTS(ctx context.Context, arg SearchActiveChunkIDsFTSParams) ([]string, error) {
	rows, err := q.query(ctx, q.searchActiveChunkIDsFTSStmt, searchActiveChunkIDsFTS,
		arg.Query,
		arg.MinCharCount,
		arg.Domain,
		arg.Cohort,
		arg.Limit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []string{}
	for rows.Next() {
		var chunk_id string
		if err := rows.Scan(&chunk_id); err != nil {
			return nil, err
		}
		items = append(items, chunk_id)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const searchDocumentIDs = `-- name: SearchDocumentIDs :many
SELECT id FROM documents
WHERE (?1 IS NULL OR domain = ?1)
  AND (?2 IS NULL OR status = ?2)
  AND (?3 IS NULL OR applicable_cohort = 'ALL' OR (',' || REPLACE(applicable_cohort, ' ', '') || ',') LIKE ('%,' || ?3 || ',%'))
  AND (?4 IS NULL OR (
      title LIKE ('%' || ?4 || '%') OR 
      doc_code LIKE ('%' || ?4 || '%')
  ))
ORDER BY priority_level DESC, publish_date DESC
LIMIT ?6 OFFSET ?5
`

type SearchDocumentIDsParams struct {
	Domain interface{} `json:"domain"`
	Status interface{} `json:"status"`
	Cohort interface{} `json:"cohort"`
	Search interface{} `json:"search"`
	Offset int64       `json:"offset"`
	Limit  int64       `json:"limit"`
}

func (q *Queries) SearchDocumentIDs(ctx context.Context, arg SearchDocumentIDsParams) ([]string, error) {
	rows, err := q.query(ctx, q.searchDocumentIDsStmt, searchDocumentIDs,
		arg.Domain,
		arg.Status,
		arg.Cohort,
		arg.Search,
		arg.Offset,
		arg.Limit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []string{}
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

